CREATE TABLE rup_requirement_comparisons (requirement_id TEXT PRIMARY KEY NOT NULL REFERENCES project_requirements(id) ON DELETE CASCADE, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, fact_id TEXT NOT NULL, certificate_id TEXT NOT NULL, certificate_name TEXT NOT NULL, issued_on TEXT NOT NULL, fact_label TEXT NOT NULL, fact_value TEXT NOT NULL, fact_page INTEGER NOT NULL, requirement_title TEXT NOT NULL, requirement_source TEXT NOT NULL, operator TEXT NOT NULL, threshold TEXT NOT NULL, interpreted_value TEXT NOT NULL, documents_fingerprint TEXT NOT NULL, version INTEGER NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX rup_comparisons_project ON rup_requirement_comparisons(project_id);
